"""Step 6: Rule-based confidence scoring, URL sanitization, and self-check quality metrics."""

from __future__ import annotations

import re
from typing import Iterable

from research.extract import build_text_fragment_url
from research.schemas import (
    ConfidenceLevel,
    Evidence,
    Insight,
    QualityMetrics,
    RejectedItem,
    Report,
    Source,
)

URL_REGEX = re.compile(r"(?:https?://|www\.)[^\s\)\]\>\"']+", re.IGNORECASE)


def strip_llm_urls(text: str) -> tuple[str, int]:
    """Remove any raw URLs generated by the LLM so only code-verified URLs appear in output."""
    if not text:
        return "", 0
    matches = URL_REGEX.findall(text)
    if not matches:
        return text, 0
    cleaned = URL_REGEX.sub("[link đã lọc]", text)
    cleaned = re.sub(r"\s+", " ", cleaned).strip()
    return cleaned, len(matches)


def score_single_insight(
    insight: Insight,
    evidence_map: dict[str, Evidence],
    source_map: dict[str, Source],
) -> Insight:
    """Compute deterministic confidence level and explanation for a single verified Insight.

    Rules (BRIEF section 4.2):
    - CAO: >= 2 distinct domains, >= 1 Tier A/B source, has fresh data (<=12m, not aging/stale only),
           no unresolved conflict, and type == 'fact' (not inference/forecast).
    - TRUNG BÌNH: 1 Tier A/B source (not stale); OR >= 2 distinct Tier C domains agreeing (not stale);
                  OR aging data (12-24m). Inference and forecasts are capped at TRUNG BÌNH and must state assumptions.
    - THẤP: Only 1 Tier C source, OR only stale data (>24m or unknown date), OR unresolved conflict.
    """
    valid_eids = [
        eid
        for eid in insight.evidence_ids
        if eid in evidence_map and evidence_map[eid].verified
    ]
    linked_sources: list[Source] = []
    for eid in valid_eids:
        ev = evidence_map[eid]
        src = source_map.get(ev.source_id)
        if src is not None:
            linked_sources.append(src)

    if not linked_sources:
        return insight.model_copy(
            update={
                "evidence_ids": [],
                "confidence": "THẤP",
                "confidence_reason": "Không có nguồn xác minh hợp lệ",
            }
        )

    unique_domains = {s.domain.lower() for s in linked_sources if s.domain}
    num_domains = max(1, len(unique_domains))
    non_stale_domains = {
        s.domain.lower() for s in linked_sources if s.domain and s.freshness != "stale"
    }
    num_non_stale_domains = len(non_stale_domains)

    tiers = [s.tier for s in linked_sources]
    has_ab = any(t in ("A", "B") for t in tiers)
    has_non_stale_ab = any(
        s.tier in ("A", "B") and s.freshness != "stale" for s in linked_sources
    )
    has_fresh_ab = any(
        s.tier in ("A", "B") and s.freshness == "fresh" for s in linked_sources
    )
    tier_summary = ", ".join(
        sorted({f"{s.id} (Hạng {s.tier}, {s.domain})" for s in linked_sources})
    )

    freshnesses = [s.freshness for s in linked_sources]
    all_stale = all(f == "stale" for f in freshnesses)
    has_fresh = any(f == "fresh" for f in freshnesses)
    only_aging_or_stale = (not has_fresh) and any(f == "aging" for f in freshnesses)

    stmt_lower = (insight.statement or "").lower()
    is_missing_data_stmt = any(
        phrase in stmt_lower
        for phrase in (
            "không có sẵn",
            "không tìm thấy dữ liệu",
            "chưa có số liệu",
            "chưa có dữ liệu",
            "không thể xác định",
        )
    )

    is_inference_or_forecast = (insight.type == "inference") or bool(insight.is_forecast)
    assumptions = list(insight.assumptions)
    if is_inference_or_forecast and not assumptions:
        assumptions = [
            "Giả định xu hướng và điều kiện thị trường hiện tại tiếp tục duy trì trong kỳ dự phóng"
        ]

    # 1. Check THẤP conditions first
    if insight.has_conflict:
        confidence: ConfidenceLevel = "THẤP"
        reason = (
            f"Các nguồn đang có số liệu/nhận định mâu thuẫn chưa giải quyết ({tier_summary})"
        )
    elif all_stale:
        confidence = "THẤP"
        reason = (
            f"Dữ liệu cũ (>24 tháng hoặc không rõ ngày đăng) từ {tier_summary}"
        )
    elif (not has_non_stale_ab) and num_non_stale_domains < 2:
        confidence = "THẤP"
        reason = f"Chỉ có 1 nguồn hạng C mới hoặc nguồn A/B không rõ ngày ({tier_summary})"
    # 2. Check CAO vs TRUNG BÌNH conditions
    elif num_non_stale_domains >= 2 and has_fresh_ab and has_fresh:
        if is_inference_or_forecast or is_missing_data_stmt:
            confidence = "TRUNG BÌNH"
            reason = (
                f"Có {num_non_stale_domains} domain độc lập gồm nguồn hạng A/B mới ({tier_summary}), "
                "nhưng là nhận định suy luận/dự báo hoặc ghi nhận thiếu dữ liệu nên tối đa TRUNG BÌNH theo quy tắc"
            )
        else:
            confidence = "CAO"
            reason = (
                f"Nhận định thực chứng (fact) từ {num_non_stale_domains} domain độc lập, "
                f"có nguồn hạng A/B mới <=12 tháng ({tier_summary}), không mâu thuẫn"
            )
    else:
        confidence = "TRUNG BÌNH"
        reasons_parts: list[str] = []
        if only_aging_or_stale:
            reasons_parts.append(f"dữ liệu cũ dần 12–24 tháng ({tier_summary})")
        elif has_non_stale_ab and num_non_stale_domains == 1:
            reasons_parts.append(f"dựa trên 1 nguồn uy tín hạng A/B ({tier_summary})")
        elif (not has_non_stale_ab) and num_non_stale_domains >= 2:
            reasons_parts.append(
                f"{num_non_stale_domains} nguồn hạng C khác domain đồng thuận ({tier_summary})"
            )
        else:
            reasons_parts.append(f"nguồn tham chiếu ({tier_summary})")

        if is_inference_or_forecast:
            reasons_parts.append("loại suy luận/dự báo (trần tối đa TRUNG BÌNH)")
        reason = "Đạt mức TRUNG BÌNH: " + "; ".join(reasons_parts)

    return insight.model_copy(
        update={
            "evidence_ids": valid_eids,
            "confidence": confidence,
            "confidence_reason": reason,
            "assumptions": assumptions,
        }
    )


def score_and_finalize_report(
    report: Report,
    total_quotes_extracted: int,
    rejected_sources: Iterable[RejectedItem] = (),
    rejected_quotes: Iterable[RejectedItem] = (),
) -> Report:
    """Enforce all evidence/URL/confidence rules on Report and compute QualityMetrics."""
    source_map = {s.id: s for s in report.sources}

    # Ensure all verified evidences have highlight_url computed by code
    updated_evidences: list[Evidence] = []
    for ev in report.evidences:
        if not ev.verified:
            continue
        src = source_map.get(ev.source_id)
        hl_url = ev.highlight_url
        if src and not hl_url:
            hl_url = build_text_fragment_url(src.url, ev.quote)
        updated_evidences.append(ev.model_copy(update={"highlight_url": hl_url}))

    evidence_map = {ev.id: ev for ev in updated_evidences}

    # Collect evidence IDs involved in conflicts
    conflict_eids: set[str] = set()
    cleaned_conflicts = []
    urls_removed_total = 0

    for c in report.conflicts:
        topic_clean, n1 = strip_llm_urls(c.topic)
        expl_clean, n2 = strip_llm_urls(c.explanation)
        vals_clean = []
        for v in c.values:
            vc, nv = strip_llm_urls(v)
            vals_clean.append(vc)
            urls_removed_total += nv
        urls_removed_total += n1 + n2
        valid_c_eids = [eid for eid in c.evidence_ids if eid in evidence_map]
        conflict_eids.update(valid_c_eids)
        cleaned_conflicts.append(
            c.model_copy(
                update={
                    "topic": topic_clean,
                    "explanation": expl_clean,
                    "values": vals_clean,
                    "evidence_ids": valid_c_eids,
                }
            )
        )

    short_clean, n_short = strip_llm_urls(report.short_answer)
    rec_clean, n_rec = strip_llm_urls(report.recommendation)
    urls_removed_total += n_short + n_rec

    if cleaned_conflicts:
        conflict_notes = []
        for c in cleaned_conflicts:
            if c.values and not all(v in short_clean for v in c.values):
                vals_str = " vs. ".join(c.values)
                conflict_notes.append(f"{c.topic} ({vals_str} — {c.explanation})")
        if conflict_notes:
            short_clean = (
                f"{short_clean} Lưu ý chênh lệch số liệu giữa các nguồn theo phạm vi/kỳ báo cáo: "
                + "; ".join(conflict_notes)
            )

    scored_insights: list[Insight] = []
    gaps_list = list(report.gaps)

    for idx, ins in enumerate(report.insights, start=1):
        stmt_clean, n_stmt = strip_llm_urls(ins.statement)
        urls_removed_total += n_stmt
        valid_eids = [eid for eid in ins.evidence_ids if eid in evidence_map]
        if not valid_eids:
            # Rule 4.2: No verified evidence -> cannot be an insight; move to data gaps
            gap_note = f"[Chưa có trích dẫn xác minh] {stmt_clean}"
            if gap_note not in gaps_list:
                gaps_list.append(gap_note)
            continue

        ins_clean = ins.model_copy(
            update={
                "id": f"I{len(scored_insights) + 1}",
                "statement": stmt_clean,
                "evidence_ids": valid_eids,
            }
        )
        scored = score_single_insight(ins_clean, evidence_map, source_map)
        scored_insights.append(scored)

    # Check high_confidence_from_tier_c_only_count (must be 0)
    high_from_c_only = 0
    for ins in scored_insights:
        if ins.confidence == "CAO":
            tiers = {
                source_map[evidence_map[eid].source_id].tier
                for eid in ins.evidence_ids
                if eid in evidence_map and evidence_map[eid].source_id in source_map
            }
            if tiers and all(t == "C" for t in tiers):
                high_from_c_only += 1

    verified_cnt = len(updated_evidences)
    total_extracted = max(total_quotes_extracted, verified_cnt)
    verified_rate = (
        round((verified_cnt / total_extracted) * 100.0, 1)
        if total_extracted > 0
        else 0.0
    )

    insights_cnt = len(scored_insights)
    insights_with_ev_cnt = sum(1 for i in scored_insights if len(i.evidence_ids) >= 1)
    insight_ev_rate = (
        round((insights_with_ev_cnt / insights_cnt) * 100.0, 1)
        if insights_cnt > 0
        else 100.0
    )

    rej_sources_list = list(rejected_sources)
    rej_quotes_list = list(rejected_quotes)

    quality = QualityMetrics(
        total_quotes_extracted=total_extracted,
        verified_quotes_count=verified_cnt,
        verified_quote_rate=verified_rate,
        total_insights_count=insights_cnt,
        insights_with_verified_evidence_rate=insight_ev_rate,
        high_confidence_from_tier_c_only_count=high_from_c_only,
        llm_invented_urls_removed_count=urls_removed_total,
        rejected_sources_count=len(rej_sources_list),
        rejected_quotes_count=len(rej_quotes_list),
        rejected_sources=rej_sources_list,
        rejected_quotes=rej_quotes_list,
    )

    return report.model_copy(
        update={
            "short_answer": short_clean,
            "recommendation": rec_clean,
            "insights": scored_insights,
            "conflicts": cleaned_conflicts,
            "gaps": gaps_list,
            "evidences": updated_evidences,
            "quality": quality,
        }
    )
